contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: take an amount to forward to c.go
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // read owner before
        address ownerBefore = c.owner();
        // read balance before
        uint256 balanceBefore = address(c).balance;

        bool reverted;
        // call c.go with the provided amount, capture revert
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read owner after
        address ownerAfter = c.owner();
        uint256 balanceAfter = address(c).balance;

        // General rule:
        // - Owner must never change as a result of the call.
        // - If the call succeeded (not reverted), the contract should forward funds so its balance is zero or at most unchanged if no funds were sent.
        assert(ownerBefore == ownerAfter && (reverted || balanceAfter == 0 || balanceAfter == balanceBefore));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: amount is Ether to send to c.go
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // observe owner and c balance before
        address ownerBefore = c.owner();
        uint balBefore = address(c).balance;

        // perform the call and capture whether it reverted
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe owner and c balance after
        address ownerAfter = c.owner();
        uint balAfter = address(c).balance;

        // GENERAL RULE: owner never changes; if the call succeeded then c's balance did not increase by amount
        assert(ownerBefore == ownerAfter && (reverted || balAfter <= balBefore));
    }

    receive() external payable { }
}
